package com.voltflow.service;
import com.voltflow.entity.ChargingStation; import com.voltflow.exception.ConflictException; import com.voltflow.exception.NotFoundException; import com.voltflow.repository.StationRepository; import lombok.RequiredArgsConstructor; import org.springframework.stereotype.Service; import org.springframework.transaction.annotation.Transactional; import java.util.List;
@Service @RequiredArgsConstructor
public class StationService { private final StationRepository repo; public List<ChargingStation> list(String q){return q==null||q.isBlank()?repo.findAll():repo.findByCityContainingIgnoreCaseOrNameContainingIgnoreCase(q,q);} public ChargingStation get(Long id){return repo.findById(id).orElseThrow(()->new NotFoundException("Station not found"));} @Transactional public ChargingStation save(ChargingStation s){if(repo.existsByNameIgnoreCaseAndCityIgnoreCase(s.getName().trim(),s.getCity().trim()))throw new ConflictException("A station with this name already exists in this city.");s.setName(s.getName().trim());s.setCity(s.getCity().trim());if(s.getChargers()!=null)s.getChargers().forEach(charger->charger.setStation(s));return repo.save(s);} @Transactional public ChargingStation update(Long id,ChargingStation input){ChargingStation s=get(id);s.setName(input.getName());s.setAddress(input.getAddress());s.setCity(input.getCity());s.setLatitude(input.getLatitude());s.setLongitude(input.getLongitude());s.setPricePerKwh(input.getPricePerKwh());s.setOperatingHours(input.getOperatingHours());s.setAvailable(input.isAvailable());return s;} @Transactional public void delete(Long id){repo.delete(get(id));} }
